from pathlib import Path
p=Path('src/app/page.tsx')
s=p.read_text(encoding='utf-8')
needle='      <section className="section career-section">'
insert='''      <section className="section archive-section" id="academic-archive">\n        <div className="shell">\n          <div className="section-kicker">ACADEMIC ARCHIVE <span /></div>\n          <div className="section-heading-row archive-heading"><div><h2>Beyond the<br /><em>publication list.</em></h2></div><p>The supplied CV and bibliography distinguish journal publications from conference outputs, supervised postgraduate work, and Prof. Sheta&apos;s own research. Each record is kept in its original category.</p></div>\n          <div className="archive-grid">\n            <div className="archive-panel">\n              <div className="archive-panel-head"><span className="archive-index">A / 31 RECORDS</span><h3>Conference presentations</h3><p>International meetings, posters, abstracts, and national scientific presentations.</p></div>\n              <div className="archive-list">{d.conferences.map((item, index) => <article className="archive-item" key={`${item.title}-${index}`}><span className="archive-year">{item.year || "—"}</span><div><strong>{item.title}</strong><small>{item.venue} · {item.location}</small></div></article>)}</div>\n            </div>\n            <div className="archive-panel">\n              <div className="archive-panel-head"><span className="archive-index">B / 20 RECORDS</span><h3>Supervised postgraduate theses</h3><p>Supervision records transcribed from the Cairo University CV; these are not publications authored by Prof. Sheta.</p></div>\n              <div className="archive-list">{d.supervisedTheses.map((item, index) => <article className="archive-item" key={`${item.title}-${index}`}><span className="archive-year">{item.year}</span><div><strong>{item.title}</strong><small>{item.degree} · {item.university}</small></div></article>)}</div>\n            </div>\n          </div>\n          <div className="own-research"><div><span className="archive-index">C / PROFESSOR&apos;S OWN RESEARCH</span><h3>Postgraduate research</h3></div><div className="own-research-list">{d.ownResearch.map((item) => <article key={item.title}><span>{item.year}</span><div><strong>{item.title}</strong><small>{item.degree} · {item.institution}</small></div></article>)}</div></div>\n          <p className="archive-note">Bibliography note: the supplied document is a verification-oriented master bibliography. Older CV-derived records and collaborative works are intentionally labeled where complete author lists or publication metadata still require confirmation.</p>\n        </div>\n      </section>\n\n'''
if needle not in s: raise SystemExit('career section marker not found')
s=s.replace(needle, insert+needle, 1)
p.write_text(s, encoding='utf-8')

css=Path('src/app/globals.css')
c=css.read_text(encoding='utf-8')
c += '''\n.archive-section{background:#dceae7}.archive-heading{align-items:start}.archive-heading>p{color:var(--muted)}.archive-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.archive-panel{background:var(--paper);border:1px solid var(--line);min-width:0}.archive-panel-head{padding:28px 26px 22px;border-bottom:1px solid var(--line)}.archive-panel-head h3{font-size:27px;margin:12px 0 10px;letter-spacing:-.04em}.archive-panel-head p{color:var(--muted);font-size:13px;line-height:1.65;max-width:430px}.archive-index{color:var(--coral);font:500 10px var(--mono);letter-spacing:.12em}.archive-list{max-height:690px;overflow:auto}.archive-item{display:grid;grid-template-columns:48px 1fr;gap:14px;padding:16px 20px;border-bottom:1px solid var(--line);transition:.2s}.archive-item:last-child{border-bottom:0}.archive-item:hover{background:var(--paper-2)}.archive-year{color:var(--cyan-2);font:500 11px var(--mono);padding-top:2px}.archive-item strong{display:block;color:var(--ink);font:600 13px var(--display);line-height:1.4;letter-spacing:-.015em}.archive-item small,.own-research small{display:block;color:var(--muted);font:11px var(--mono);line-height:1.55;margin-top:5px}.own-research{display:grid;grid-template-columns:1fr 2fr;gap:35px;margin-top:20px;padding:30px 26px;background:var(--ink);color:white}.own-research h3{font-size:27px;margin-top:12px}.own-research-list{display:grid;grid-template-columns:1fr 1fr;gap:14px}.own-research-list article{display:grid;grid-template-columns:42px 1fr;gap:12px;border-top:1px solid rgba(117,227,220,.25);padding-top:14px}.own-research-list article>span{color:var(--cyan);font:11px var(--mono)}.own-research strong{display:block;font:600 14px var(--display);line-height:1.4}.own-research small{color:rgba(255,255,255,.55)}.archive-note{margin:20px 0 0;color:var(--muted);font:11px var(--mono);line-height:1.7;max-width:800px}@media(max-width:900px){.archive-grid{grid-template-columns:1fr}.archive-list{max-height:none}.own-research{grid-template-columns:1fr;gap:25px}}@media(max-width:520px){.archive-panel-head{padding:22px 18px}.archive-item{grid-template-columns:40px 1fr;padding:14px}.own-research{padding:24px 18px}.own-research-list{grid-template-columns:1fr}}\n'''
css.write_text(c, encoding='utf-8')
print('Inserted academic archive UI and responsive styles')
